FROM teacher
WHERE id = #{id}

SELECT id, user_id, teacher_no, name, gender, title, college, phone, email, create_time, update_time
FROM teacher
WHERE user_id = #{userId}

SELECT id, user_id, teacher_no, name, gender, title, college, phone, email, create_time, update_time
FROM teacher
